fn context_actions(
    mode: DocumentMode,
    table_available: bool,
    task_available: bool,
    source_selection_available: bool,
) -> Vec<ContextAction> {
    let mut actions = match mode {
        DocumentMode::Reading => vec![
            ContextAction::CopyText,
            ContextAction::CopyMarkdown,
            ContextAction::CopyPlatform,
            ContextAction::StudyTools,
        ],
        DocumentMode::SourceEditing | DocumentMode::Split => vec![
            ContextAction::Paste,
            ContextAction::Bold,
            ContextAction::Italic,
            ContextAction::Link,
            ContextAction::Task,
            ContextAction::BlockTools,
            ContextAction::InsertTools,
            ContextAction::StudyTools,
        ],
    };
    if mode.is_editable() && source_selection_available {
        actions.insert(1, ContextAction::Cut);
        actions.push(ContextAction::CopyText);
        actions.push(ContextAction::CopyMarkdown);
    }
    if mode == DocumentMode::Reading && task_available {
        actions.insert(0, ContextAction::ToggleTask);
    }
    if table_available {
        actions.push(ContextAction::CopyTableTsv);
    }
    actions
}

fn context_menu_row_height(window_height: f32, action_count: usize) -> f32 {
    (window_height / action_count.max(1) as f32).clamp(28.0, CONTEXT_MENU_ROW_HEIGHT)
}

fn context_action_at(menu: &ContextMenu, pointer: (f32, f32)) -> Option<ContextAction> {
    let (_, top) = menu.origin;
    let (x, y) = pointer;
    if !(menu.origin.0..=menu.origin.0 + CONTEXT_MENU_WIDTH).contains(&x)
        || !(top..=top + menu.row_height * menu.actions.len() as f32).contains(&y)
    {
        return None;
    }
    menu.actions
        .get(((y - top) / menu.row_height) as usize)
        .copied()
}

/// Un menú contextual propio es una capa efímera: Escape lo descarta y el
/// resto del teclado no llega al editor que queda visualmente detrás.
fn transient_menu_dismisses_for(key: KeyCode, state: ElementState) -> bool {
    state == ElementState::Pressed && key == KeyCode::Escape
}

#[derive(Default)]
struct TraversalState {
    degradation: Option<Degradation>,
}

impl TraversalState {
    fn mark(&mut self, reason: Degradation) {
        if self.degradation.is_none() {
            self.degradation = Some(reason);
        }
    }
}

struct ParseOutcome {
    blocks: Vec<Block>,
    degradation: Option<Degradation>,
}

/// La extensión elegida para el archivo es una política de contenido, no una
/// conclusión del parser. Un texto inerte sigue siéndolo al editar o alternar
/// la vista, aunque contenga caracteres que parecen Markdown.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum DocumentContentKind {
    Markdown,
    InertText,
}

impl DocumentContentKind {
    fn for_path(path: &std::path::Path) -> Self {
        if is_markdown_path(path) {
            Self::Markdown
        } else {
            Self::InertText
        }
    }

    fn prepare_view(self, source: &str) -> Result<ParseOutcome, &'static str> {
        match self {
            Self::Markdown => parse_blocks(source),
            Self::InertText => {
                let source_index = SourceIndex::new(source);
                safe_source_blocks(source, &source_index).map(|blocks| ParseOutcome {
                    blocks,
                    degradation: Some(Degradation::TextOnly),
                })
            }
        }
    }
}

