    fn new_recovery_session(&self) -> Option<RecoverySession> {
        self.recovery_enabled
            .then(RecoverySession::start)
            .and_then(Result::ok)
    }

    fn next_recovery_deadline(&self) -> Option<Instant> {
        earliest_recovery_deadline(
            std::iter::once(&self.document)
                .chain(self.inactive_documents.iter().map(|tab| &tab.document)),
        )
    }

    /// Materializa únicamente las recuperaciones cuya pausa de escritura ya
    /// venció. La lista se reúne antes de crear hilos para no retener préstamos
    /// de pestañas mientras se interactúa con disco.
    fn flush_due_recoveries(&mut self, now: Instant) {
        self.flush_recoveries(Some(now));
    }

    /// Escribe de inmediato lo que está esperando su plazo: al perder el foco,
    /// cambiar de pestaña o abrir un diálogo la persona puede irse sin volver.
    fn flush_recoveries_now(&mut self) {
        self.flush_recoveries(None);
    }

    /// Con `Some(now)`, solo lo vencido; con `None`, todo lo pendiente. Las
    /// copias van al hilo escritor, que no bloquea la interfaz.
    /// Pasa a cada copia el título y el origen actuales de su documento.
    fn refresh_recovery_meta(&self) {
        if let Some(recovery) = &self.recovery {
            recovery.set_meta(self.document.recovery_meta());
        }
        for tab in &self.inactive_documents {
            if let Some(recovery) = &tab.recovery {
                recovery.set_meta(tab.document.recovery_meta());
            }
        }
    }

    fn flush_recoveries(&mut self, due: Option<Instant>) {
        self.refresh_recovery_meta();
        let take = |document: &mut DocumentState| match due {
            Some(now) => document.take_due_recovery(now),
            None => document.take_pending_recovery(),
        };
        let mut pending = Vec::new();
        if let (Some(recovery), Some(request)) = (self.recovery.clone(), take(&mut self.document)) {
            pending.push((recovery, self.document.full_text(), request));
        }
        for tab in &mut self.inactive_documents {
            if let (Some(recovery), Some(request)) = (tab.recovery.clone(), take(&mut tab.document))
            {
                pending.push((recovery, tab.document.full_text(), request));
            }
        }
        for (recovery, source, request) in pending {
            recovery.submit(source, request);
        }
        self.report_recovery_failure();
    }

    /// Si una copia no se pudo escribir, la persona lo sabe: sin ese aviso
    /// creería tener una copia que no existe.
    fn report_recovery_failure(&mut self) {
        let failed = self
            .recovery
            .iter()
            .chain(
                self.inactive_documents
                    .iter()
                    .filter_map(|tab| tab.recovery.as_ref()),
            )
            .fold(false, |failed, recovery| {
                recovery.take_new_failure() | failed
            });
        if failed {
            self.log
                .push("[recuperación] no se pudo escribir una copia".into());
            self.set_notice("No se pudo guardar la copia de recuperación: guardá el documento");
        }
    }

    fn toggle_recovery(&mut self) {
        if self.recovery_enabled {
            self.open_dialog(Dialog::disable_recovery(), None);
            return;
        }
        self.apply_recovery_toggle();
    }

    fn apply_recovery_toggle(&mut self) {
        self.recovery_enabled = !self.recovery_enabled;
        if self.recovery_enabled {
            self.recovery = RecoverySession::start().ok();
            for tab in &mut self.inactive_documents {
                tab.recovery = RecoverySession::start().ok();
            }
            self.recovery_privacy_notice_pending =
                RecoverySession::privacy_notice_needed().unwrap_or(false);
            self.set_notice("Recuperación activada");
        } else {
            self.document.cancel_pending_recovery();
            if let Some(recovery) = self.recovery.take() {
                let _ = recovery.clear();
            }
            for tab in &mut self.inactive_documents {
                tab.document.cancel_pending_recovery();
                if let Some(recovery) = tab.recovery.take() {
                    let _ = recovery.clear();
                }
            }
            self.recovery_privacy_notice_pending = false;
            self.set_notice("Recuperación desactivada");
        }
        self.settings.recovery_enabled = self.recovery_enabled;
        if self.settings.store().is_err() {
            self.set_notice("la preferencia de recuperación no pudo guardarse");
        }
    }

    /// Nombre de una acción en la paleta. Las que activan o desactivan algo
    /// dicen su estado actual: «Movimiento reducido: activado».
    fn action_display_name(&self, action: AppAction) -> String {
        let (base, enabled) = match action {
            AppAction::ToggleReduceMotion => ("Movimiento reducido", self.reduce_motion),
            AppAction::ToggleRecovery => ("Recuperación de cambios", self.recovery_enabled),
            AppAction::ToggleFloatingOutline => ("Índice flotante", self.settings.floating_outline),
            AppAction::ToggleOpenExternalInExisting => (
                "Abrir archivos externos en la ventana abierta",
                self.settings.open_external_in_existing,
            ),
            AppAction::TogglePinOnTop => ("Ventana siempre encima", self.pinned_on_top),
            AppAction::ToggleTheme => ("Tema de noche", self.palette.bg.0 < 0x80),
            _ => return action_name(action).to_string(),
        };
        format!(
            "{base}: {}",
            if enabled {
                "activado ✓"
            } else {
                "desactivado"
            }
        )
    }

    /// Menú de la fila 1 que está abierto (Archivo, Vista o Carpeta).
    fn open_top_menu(&self) -> Option<AppAction> {
        self.open_surface().filter(|action| is_top_menu(*action))
    }

    /// Pasa al menú vecino con ← y →, dando la vuelta.
    fn switch_top_menu(&mut self, forward: bool) {
        const MENUS: [AppAction; 4] = [
            AppAction::MenuFile,
            AppAction::MenuEdit,
            AppAction::MenuView,
            AppAction::MenuFolder,
        ];
        let Some(current) = self.open_top_menu() else {
            return;
        };
        let position = MENUS.iter().position(|menu| *menu == current).unwrap_or(0);
        let next = MENUS[(position + if forward { 1 } else { MENUS.len() - 1 }) % MENUS.len()];
        self.press_toolbar_action(next);
    }

    fn open_command_palette(&mut self) {
        self.clear_pane_split_picker();
        self.context_menu = None;
        self.search_query = None;
        self.workspace_search_query = None;
        self.workspace_paths = None;
        self.backlink_paths = None;
        self.outline_headings = None;
        self.command_palette = Some(0);
        self.command_palette_query.clear();
        self.command_palette_scope = CommandPaletteScope::All;
        self.toolbar_focus = None;
        if let Some(window) = &self.window {
            window.request_redraw();
        }
    }

    fn handle_toolbar_key(&mut self, event: &KeyEvent) {
        if event.state != ElementState::Pressed || event.repeat {
            return;
        }
        let Some(index) = self.toolbar_focus else {
            return;
        };
        let width = self.view_size().map_or(900.0, |size| size.0);
        let focus_count = toolbar_focus_count(self.document.mode, width);
        match event.physical_key {
            PhysicalKey::Code(KeyCode::Escape | KeyCode::F6) => self.toolbar_focus = None,
            PhysicalKey::Code(KeyCode::ArrowLeft) => {
                self.toolbar_focus = Some(adjacent_toolbar_index(index, true, focus_count));
            }
            PhysicalKey::Code(KeyCode::ArrowRight | KeyCode::Tab) => {
                self.toolbar_focus = Some(adjacent_toolbar_index(index, false, focus_count));
            }
            PhysicalKey::Code(KeyCode::Enter | KeyCode::Space) => {
                self.toolbar_focus = None;
                if let Some(target) = toolbar_focus_mode(index) {
                    self.select_mode(target);
                } else if let Some(action) = toolbar_focus_action(index, self.document.mode, width)
                {
                    self.press_toolbar_action(action);
                }
            }
            _ => return,
        }
        if let Some(window) = &self.window {
            window.request_redraw();
        }
    }

    fn handle_command_palette_key(&mut self, event: &KeyEvent) {
        if event.state != ElementState::Pressed || event.repeat {
            return;
        }
        let Some(selected) = self.command_palette else {
            return;
        };
        let entries = self.command_palette_entries();
        let selected = menu::snap(&entries, selected);
        match event.physical_key {
            PhysicalKey::Code(KeyCode::Escape) => {
                self.command_palette = None;
                self.command_palette_query.clear();
            }
            PhysicalKey::Code(KeyCode::Backspace) => {
                self.command_palette_query.pop();
                self.command_palette = Some(0);
            }
            PhysicalKey::Code(KeyCode::ArrowDown | KeyCode::Tab) if !entries.is_empty() => {
                self.command_palette = Some(menu::step(&entries, selected, true));
            }
            PhysicalKey::Code(KeyCode::ArrowUp) if !entries.is_empty() => {
                self.command_palette = Some(menu::step(&entries, selected, false));
            }
            PhysicalKey::Code(KeyCode::ArrowLeft | KeyCode::ArrowRight)
                if self.command_palette_query.is_empty() && self.open_top_menu().is_some() =>
            {
                let forward = event.physical_key == PhysicalKey::Code(KeyCode::ArrowRight);
                self.switch_top_menu(forward);
            }
            PhysicalKey::Code(KeyCode::Enter) if !entries.is_empty() => {
                if let Some(action) = entries.get(selected).and_then(|entry| entry.action()) {
                    self.command_palette = None;
                    self.command_palette_query.clear();
                    self.command_palette_scope = CommandPaletteScope::All;
                    self.perform_action(action);
                }
            }
            _ => {
                let text = typed_text(
                    event.text.as_deref(),
                    self.modifiers.control_key(),
                    self.modifiers.alt_key(),
                );
                if let Some(text) = text {
                    self.append_command_palette_text(text);
                } else {
                    return;
                }
            }
        }
        if let Some(window) = &self.window {
            window.request_redraw();
        }
    }

    fn append_command_palette_text(&mut self, text: &str) {
        if text.chars().any(char::is_control) {
            return;
        }
        append_limited_text(
            &mut self.command_palette_query,
            text,
            MAX_SEARCH_QUERY_CHARS,
        );
        self.command_palette = Some(0);
    }

    /// Filas de la paleta o menú abierto. Sin texto escrito conservan sus
    /// grupos con encabezado; al filtrar, solo las acciones que coinciden.
    fn command_palette_entries(&self) -> Vec<MenuEntry> {
        if !self.command_palette_query.trim().is_empty() {
            return menu::items(&self.command_palette_actions());
        }
        match self.command_palette_scope {
            CommandPaletteScope::All => menu::items(&APP_ACTIONS),
            CommandPaletteScope::File => grouped_entries(&FILE_GROUPS),
            CommandPaletteScope::Edit => grouped_entries(&EDIT_GROUPS),
            CommandPaletteScope::View => grouped_entries(&VIEW_GROUPS),
            CommandPaletteScope::Folder => grouped_entries(&FOLDER_GROUPS),
            CommandPaletteScope::Menu => grouped_entries(&MENU_GROUPS),
            CommandPaletteScope::Blocks => grouped_entries(&BLOCK_GROUPS),
            CommandPaletteScope::Insert => menu::items(&INSERT_ACTIONS),
            CommandPaletteScope::Workspace => menu::items(&WORKSPACE_HUB_ACTIONS),
            CommandPaletteScope::Study => grouped_entries(&STUDY_GROUPS),
        }
    }

    fn command_palette_actions(&self) -> Vec<AppAction> {
        let actions = match self.command_palette_scope {
            CommandPaletteScope::All | CommandPaletteScope::Menu => &APP_ACTIONS[..],
            CommandPaletteScope::File => &FILE_ACTIONS[..],
            CommandPaletteScope::Edit => &EDIT_ACTIONS[..],
            CommandPaletteScope::View => &VIEW_ACTIONS[..],
            CommandPaletteScope::Folder => &FOLDER_ACTIONS[..],
            CommandPaletteScope::Blocks => &BLOCK_ACTIONS[..],
            CommandPaletteScope::Insert => &INSERT_ACTIONS[..],
            CommandPaletteScope::Workspace => &WORKSPACE_HUB_ACTIONS[..],
            CommandPaletteScope::Study => &STUDY_ACTIONS[..],
        };
        filtered_actions_from(actions, &self.command_palette_query)
    }

