    #[test]
    fn la_categoria_de_una_accion_es_su_grupo_del_menu() {
        assert_eq!(action_category(AppAction::Save), Some("Archivo"));
        assert_eq!(action_category(AppAction::Undo), Some("Editar"));
        assert_eq!(action_category(AppAction::CommandPalette), Some("Buscar"));
        // Toda acción de la paleta tiene categoría.
        let sin_categoria: Vec<_> = APP_ACTIONS
            .iter()
            .filter(|action| action_category(**action).is_none())
            .collect();
        assert!(sin_categoria.is_empty(), "{sin_categoria:?}");
    }

    #[test]
    fn toda_accion_de_la_paleta_esta_en_un_menu_o_se_declara_solo_paleta() {
        let en_menus = [
            &FILE_ACTIONS[..],
            &EDIT_ACTIONS[..],
            &VIEW_ACTIONS[..],
            &FOLDER_ACTIONS[..],
            &BLOCK_ACTIONS[..],
            &INSERT_ACTIONS[..],
            &STUDY_ACTIONS[..],
            // Los botones de la barra de edición y de lectura.
            &EDITING_CONTEXT_TOOLBAR_ACTIONS[..],
            &READING_CONTEXT_TOOLBAR_ACTIONS[..],
            &PRIMARY_TOOLBAR_ACTIONS[..],
        ];
        let sueltas = APP_ACTIONS
            .iter()
            .filter(|accion| !en_menus.iter().any(|menu| menu.contains(accion)))
            .copied()
            .collect::<Vec<_>>();
        assert_eq!(
            sueltas, PALETTE_ONLY,
            "una acción nueva va en un menú o en PALETTE_ONLY"
        );
        // Ningún menú repite una acción.
        for (nombre, grupos) in [
            ("Archivo", &FILE_GROUPS[..]),
            ("Editar", &EDIT_GROUPS[..]),
            ("Vista", &VIEW_GROUPS[..]),
            ("Carpeta", &FOLDER_GROUPS[..]),
            ("Párrafo", &BLOCK_GROUPS[..]),
            ("Estudio", &STUDY_GROUPS[..]),
        ] {
            let mut vistas = Vec::new();
            for (_, acciones) in grupos {
                for accion in *acciones {
                    assert!(!vistas.contains(accion), "{nombre} repite {accion:?}");
                    vistas.push(*accion);
                }
            }
        }
    }

