    #[test]
    fn un_menu_con_grupos_salta_los_encabezados_con_teclado_y_con_clic() {
        let mut app = App::for_tests(NIGHT);
        app.load_for_test("", DocumentMode::SourceEditing);
        app.draw_for_test(900, 560);
        app.open_block_actions();
        let entradas = app.command_palette_entries();
        assert!(entradas[0].is_heading());
        assert_eq!(entradas.len(), 13, "3 encabezados y 10 acciones");
        // La lista expone todas las filas y la elegida nunca es un encabezado.
        let lista = app.open_list().expect("el menú es una lista abierta");
        assert_eq!(lista.total, 13);
        assert_eq!(lista.selected, 1);
        // Home y End caen en elementos, no en encabezados.
        app.navigate_open_list(list_view::ListNav::Home);
        assert!(!entradas[app.open_list().expect("abierta").selected].is_heading());
        // La fila 0 es un encabezado: no tiene acción que ejecutar.
        app.draw_for_test(900, 560);
        let geometria = app
            .navigation_panel_geometry(lista.total)
            .expect("hay geometría");
        let (x, y) = (
            geometria.x + 40.0,
            geometria.items_y + PANEL_ROW_HEIGHT * 0.5,
        );
        let fila = app.list_item_at(x, y, lista.total, lista.selected);
        assert_eq!(fila, Some(0));
        assert!(entradas[0].action().is_none());
        assert!(app.command_palette.is_some());
        // Con texto escrito el menú es una lista plana sin encabezados.
        app.append_command_palette_text("cita");
        assert!(
            app.command_palette_entries()
                .iter()
                .all(|e| !e.is_heading())
        );
    }

    #[test]
    fn un_documento_nuevo_se_llama_como_su_primer_titulo_y_avisa_que_no_esta_guardado() {
        let mut app = App::for_tests(NIGHT);
        // «Nuevo apunte» de la bienvenida: ya es un documento nuevo, vacío.
        app.document.welcome = false;
        // Vacío: sin título y sin marca (no hay nada que perder).
        assert!(app.document.is_untitled());
        assert_eq!(app.document.display_name(), titulo::UNTITLED_NAME);
        assert!(!app.document.is_unsaved());
        assert_eq!(tab_label_for(&app.document, 40), titulo::UNTITLED_NAME);
        // Con texto: toma el título y lleva la marca de sin guardar.
        app.load_for_test(
            "# Apuntes de biología

texto",
            DocumentMode::SourceEditing,
        );
        assert_eq!(app.document.display_name(), "Apuntes de biología");
        assert!(app.document.is_unsaved());
        let etiqueta = tab_label_for(&app.document, 40);
        assert_eq!(
            etiqueta,
            format!("Apuntes de biología {}", titulo::UNSAVED_MARK)
        );
        // Cambiar el título del texto cambia el nombre.
        app.load_for_test(
            "# Otro tema
",
            DocumentMode::SourceEditing,
        );
        assert_eq!(app.document.display_name(), "Otro tema");
        // El nombre que se propone al guardar sale del título.
        assert_eq!(app.document.suggested_stem(), "Otro tema");
        // Un archivo guardado conserva el nombre de su archivo.
        app.document.path = r"C:
otas\clase.md"
            .to_string();
        app.document.source_identity = None;
        assert!(!app.document.is_untitled());
        assert_eq!(app.document.display_name(), "clase.md");
        assert_eq!(app.document.suggested_stem(), "clase");
    }

