    #[test]
    fn la_barra_de_pestanas_resuelve_cada_destino_sin_salir_de_su_area() {
        // Pestañas arriba, bajo la barra de ventana; el botón `+` va detrás.
        let y = TAB_STRIP_Y + TAB_STRIP_HEIGHT * 0.5;
        assert_eq!(tab_index_at(20.0, y, 600.0, 600.0, 3), Some(0));
        assert_eq!(tab_index_at(200.0, y, 600.0, 600.0, 3), Some(1));
        assert_eq!(tab_index_at(400.0, y, 600.0, 600.0, 3), Some(2));
        assert_eq!(
            tab_index_at(20.0, DOCUMENT_VIEWPORT_TOP + 10.0, 600.0, 600.0, 3),
            None
        );
        assert_eq!(tab_index_at(20.0, 580.0, 600.0, 600.0, 3), None);
        assert_eq!(tab_index_at(590.0, y, 600.0, 600.0, 2), None);
        assert_eq!(tab_close_index_at(180.0, y, 600.0, 600.0, 3), Some(0));
        assert_eq!(tab_close_index_at(150.0, y, 600.0, 600.0, 3), None);
        assert!(new_tab_button_at(460.0, y, 600.0, 2));
        assert!(!new_tab_button_at(
            460.0,
            DOCUMENT_VIEWPORT_TOP + 10.0,
            600.0,
            2
        ));
        assert_eq!(tab_index_at(460.0, y, 600.0, 600.0, 2), None);
        const {
            assert!(CONTEXT_TOOLBAR_Y >= TAB_STRIP_Y + TAB_STRIP_HEIGHT);
            assert!(DOCUMENT_VIEWPORT_TOP >= CONTEXT_TOOLBAR_Y + CONTEXT_TOOLBAR_HEIGHT);
        };
    }

    #[test]
    fn las_pestanas_fijadas_son_compactas_van_primero_y_no_tienen_cierre() {
        let y = TAB_STRIP_Y + TAB_STRIP_HEIGHT * 0.5;
        let strip = TabStrip::new(4, 2);
        let ancho = 900.0;
        let fijada = pinned_tab_width(ancho, strip);
        assert!(fijada <= PINNED_TAB_WIDTH);
        assert!(fijada < tab_width(ancho, strip));
        // Las dos primeras son fijadas y las demás siguen sin huecos ni solapes.
        let mut fin = TAB_STRIP_X;
        for index in 0..4 {
            let (izquierda, ancho_pestana) = tab_span(ancho, strip, index);
            assert!(
                (izquierda - fin).abs() < 0.01,
                "la pestaña {index} deja un hueco"
            );
            assert_eq!(
                tab_index_at(izquierda + ancho_pestana * 0.5, y, ancho, 600.0, strip),
                Some(index)
            );
            fin = izquierda + ancho_pestana;
        }
        assert!((new_tab_button_x(ancho, strip) - (fin + 2.0)).abs() < 0.01);
        // La ✕ solo está en las no fijadas.
        let (izquierda, ancho_pestana) = tab_span(ancho, strip, 0);
        assert_eq!(
            tab_close_index_at(izquierda + ancho_pestana - 8.0, y, ancho, 600.0, strip),
            None
        );
        let (izquierda, ancho_pestana) = tab_span(ancho, strip, 2);
        assert_eq!(
            tab_close_index_at(izquierda + ancho_pestana - 8.0, y, ancho, 600.0, strip),
            Some(2)
        );
        // Con todas fijadas no queda pestaña normal que medir.
        assert_eq!(tab_width(ancho, TabStrip::new(2, 2)), 0.0);
        assert_eq!(
            tab_index_at(2000.0, y, ancho, 600.0, TabStrip::new(2, 2)),
            None
        );
    }

    #[test]
    fn los_divisores_siguen_al_arbol_y_respetan_los_limites() {
        let area = PaneGeometry {
            x: 0.0,
            y: 0.0,
            width: 1_000.0,
            height: 600.0,
        };
        let mut tree = DocumentPaneTree::single(1);
        let primero = tree.first_pane_id();
        let segundo = tree
            .split_pane(primero, 2, DocumentPaneAxis::Vertical)
            .expect("divide a la derecha");
        let tercero = tree
            .split_pane(segundo, 3, DocumentPaneAxis::Horizontal)
            .expect("divide la hoja derecha hacia abajo");

        let divisores = tree.dividers(area);
        assert_eq!(divisores.len(), 2);
        // La raíz (vertical) va primero y su franja está centrada en el borde.
        assert_eq!(divisores[0].axis, DocumentPaneAxis::Vertical);
        assert!((divisores[0].rect.x + DIVIDER_THICKNESS * 0.5 - 500.0).abs() < 0.01);
        assert_eq!(divisores[0].rect.height, 600.0);
        // La anidada reparte solo la mitad derecha.
        assert_eq!(divisores[1].axis, DocumentPaneAxis::Horizontal);
        assert_eq!(divisores[1].region.x, 500.0);
        assert_eq!(divisores[1].region.width, 500.0);
        assert_eq!(
            divider_at(&divisores, 500.0, 100.0).map(|d| d.index),
            Some(0)
        );
        assert_eq!(
            divider_at(&divisores, 700.0, 300.0).map(|d| d.index),
            Some(1)
        );
        assert_eq!(divider_at(&divisores, 250.0, 100.0), None);

        // El arrastre respeta 15–85 % y el mínimo útil de 240 px.
        assert_eq!(divider_fraction_for_pointer(divisores[0], 0.0, 0.0), 0.24);
        assert_eq!(divider_fraction_for_pointer(divisores[0], 999.0, 0.0), 0.76);
        assert_eq!(divider_fraction_for_pointer(divisores[0], 400.0, 0.0), 0.4);
        // Una región que no admite dos mínimos vuelve al centro.
        let angosta = PaneDivider {
            region: PaneGeometry {
                width: 400.0,
                ..area
            },
            ..divisores[0]
        };
        assert_eq!(divider_fraction_for_pointer(angosta, 50.0, 0.0), 0.5);

        assert!(tree.set_split_fraction(0, 0.7));
        assert!(!tree.set_split_fraction(5, 0.7));
        assert_eq!(tree.dividers(area)[0].fraction, 0.7);
        assert_eq!(normalized_pane_fraction(0.01), 0.15);
        assert_eq!(normalized_pane_fraction(0.99), 0.85);
        assert_eq!(normalized_pane_fraction(f32::NAN), 0.5);

        // El teclado elige la división más cercana en el sentido de la flecha.
        assert_eq!(
            tree.nearest_split_of(tercero, DocumentPaneAxis::Horizontal)
                .map(|(index, _)| index),
            Some(1)
        );
        assert_eq!(
            tree.nearest_split_of(tercero, DocumentPaneAxis::Vertical)
                .map(|(index, _)| index),
            Some(0)
        );
        assert_eq!(
            tree.nearest_split_of(primero, DocumentPaneAxis::Horizontal),
            None
        );
    }

    #[test]
    fn el_divisor_es_un_objetivo_se_arrastra_y_el_teclado_lo_mueve_por_pasos() {
        let mut app = App::for_tests(NIGHT);
        app.load_for_test("uno", DocumentMode::Reading);
        app.perform_action(AppAction::NewDocument);
        app.open_document_pane_picker(DocumentPaneAxis::Vertical);
        app.choose_document_pane_split(2);
        app.draw_for_test(1_100, 720);

        let y = DOCUMENT_VIEWPORT_TOP + 300.0;
        assert_eq!(app.ui_target_at(550.0, y), Some(UiTarget::PaneDivider(0)));
        assert_ne!(app.ui_target_at(300.0, y), Some(UiTarget::PaneDivider(0)));

        app.drag_divider_to(0, 660.0, y);
        let fraccion = app.pane_dividers()[0].fraction;
        assert!((fraccion - 0.6).abs() < 0.001, "{fraccion}");
        // El divisor se movió con él.
        assert_eq!(app.ui_target_at(660.0, y), Some(UiTarget::PaneDivider(0)));

        app.nudge_pane_divider(KeyCode::ArrowLeft);
        assert!((app.pane_dividers()[0].fraction - 0.55).abs() < 0.001);
        // Una flecha de otro sentido no mueve un divisor vertical.
        app.nudge_pane_divider(KeyCode::ArrowDown);
        assert!((app.pane_dividers()[0].fraction - 0.55).abs() < 0.001);
        // Nunca cruza el mínimo útil: 240 px de 1100 son 21,8 %.
        for _ in 0..20 {
            app.nudge_pane_divider(KeyCode::ArrowLeft);
        }
        assert!(app.pane_dividers()[0].fraction >= 240.0 / 1_100.0 - 0.001);
    }

    #[test]
    fn intercambiar_paneles_y_dividir_con_un_lado_conservan_documento_y_vista() {
        let mut tree = DocumentPaneTree::single(1);
        let a = tree.first_pane_id();
        let b = tree
            .split_pane(a, 2, DocumentPaneAxis::Vertical)
            .expect("divide");
        tree.set_pane_scroll(a, 40.0);
        tree.set_pane_scroll(b, 90.0);
        let area = PaneGeometry {
            x: 0.0,
            y: 0.0,
            width: 1_000.0,
            height: 600.0,
        };
        assert!(tree.swap_panes(a, b));
        let layouts = document_pane_layouts_in(&tree, area);
        // Ahora el documento 2 va a la izquierda, con su vista y su posición.
        assert_eq!(layouts[0].pane_id, b);
        assert_eq!(layouts[0].document_id, 2);
        assert_eq!(tree.pane_scroll(b), Some(90.0));
        assert_eq!(layouts[1].pane_id, a);
        assert_eq!(tree.pane_scroll(a), Some(40.0));
        assert!(!tree.swap_panes(a, a));
        assert!(!tree.swap_panes(a, 9_999));

        // Dividir con el documento nuevo antes del existente.
        let c = tree
            .split_pane_side(a, 3, DocumentPaneAxis::Horizontal, true)
            .expect("divide con el nuevo arriba");
        let layouts = document_pane_layouts_in(&tree, area);
        let arriba = layouts.iter().find(|layout| layout.pane_id == c).unwrap();
        let abajo = layouts.iter().find(|layout| layout.pane_id == a).unwrap();
        assert!(arriba.geometry.y < abajo.geometry.y);
        assert_eq!(tree.pane_count(), 3);
    }

    #[test]
    fn el_soltado_distingue_centro_y_bordes_de_un_panel() {
        let rect = PaneGeometry {
            x: 100.0,
            y: 50.0,
            width: 400.0,
            height: 200.0,
        };
        assert_eq!(drop_zone(rect, 300.0, 150.0), DropZone::Center);
        assert_eq!(drop_zone(rect, 110.0, 150.0), DropZone::Left);
        assert_eq!(drop_zone(rect, 490.0, 150.0), DropZone::Right);
        assert_eq!(drop_zone(rect, 300.0, 55.0), DropZone::Top);
        assert_eq!(drop_zone(rect, 300.0, 245.0), DropZone::Bottom);
        // En una esquina manda el borde más cercano.
        assert_eq!(drop_zone(rect, 102.0, 60.0), DropZone::Left);
        assert_eq!(drop_zone(rect, 300.0, 150.0 + 1_000.0), DropZone::Bottom);
    }

    /// Dos paneles con dos documentos y una tercera pestaña en la tira.
    fn mosaico_con_tira() -> (App, u64) {
        let mut app = App::for_tests(NIGHT);
        app.load_for_test("uno", DocumentMode::Reading);
        app.perform_action(AppAction::NewDocument);
        app.perform_action(AppAction::NewDocument);
        let en_la_tira = app.document.id;
        app.open_document_pane_picker(DocumentPaneAxis::Vertical);
        let candidato = app
            .pane_split_candidates
            .iter()
            .position(|id| *id != SPLIT_NEW_DOCUMENT && *id != SPLIT_OPEN_FILE && *id != en_la_tira)
            .expect("hay otra pestaña para dividir");
        app.choose_document_pane_split(candidato);
        app.draw_for_test(1_100, 720);
        assert_eq!(app.document_panes.pane_count(), 2);
        // La tira lista todas las pestañas; la que no ocupa un panel es la
        // que sirve para soltar y arrastrar.
        let mut en_paneles = Vec::new();
        app.document_panes.document_ids(&mut en_paneles);
        let tira: Vec<u64> = app
            .visible_tab_ids()
            .into_iter()
            .filter(|id| !en_paneles.contains(id))
            .collect();
        assert_eq!(tira.len(), 1);
        (app, tira[0])
    }

    /// Pestañas de la tira que no ocupan un panel.
    fn fuera_de_paneles(app: &App) -> Vec<u64> {
        let mut en_paneles = Vec::new();
        app.document_panes.document_ids(&mut en_paneles);
        app.visible_tab_ids()
            .into_iter()
            .filter(|id| !en_paneles.contains(id))
            .collect()
    }

    fn arrastrar(app: &mut App, origen: MosaicSource, destino: (f32, f32)) {
        app.mosaic_drag = Some(MosaicDrag {
            source: origen,
            origin: (0.0, 0.0),
            active: true,
        });
        app.pointer = Some(destino);
        app.finish_mosaic_drag();
    }

    #[test]
    fn arrastrar_una_cabecera_sobre_otra_intercambia_los_paneles() {
        let (mut app, _) = mosaico_con_tira();
        let antes = app.visible_document_pane_layouts();
        let y = DOCUMENT_VIEWPORT_TOP + 300.0;
        arrastrar(&mut app, MosaicSource::Pane(antes[0].pane_id), (825.0, y));
        let despues = app.visible_document_pane_layouts();
        assert_eq!(despues[0].document_id, antes[1].document_id);
        assert_eq!(despues[1].document_id, antes[0].document_id);
        // Soltar sobre sí mismo o fuera de un panel no cambia nada.
        arrastrar(&mut app, MosaicSource::Pane(despues[0].pane_id), (275.0, y));
        assert_eq!(
            app.visible_document_pane_layouts()[0].document_id,
            despues[0].document_id
        );
    }

    #[test]
    fn soltar_una_pestana_en_el_centro_reemplaza_y_en_el_borde_divide() {
        let (mut app, en_la_tira) = mosaico_con_tira();
        let y = DOCUMENT_VIEWPORT_TOP + 300.0;
        let reemplazado = app.visible_document_pane_layouts()[1].document_id;
        arrastrar(&mut app, MosaicSource::Tab(en_la_tira), (825.0, y));
        let capas = app.visible_document_pane_layouts();
        assert_eq!(capas.len(), 2);
        assert!(capas.iter().any(|layout| layout.document_id == en_la_tira));
        assert_eq!(
            fuera_de_paneles(&app),
            vec![reemplazado],
            "el reemplazado vuelve a la tira"
        );

        // Una pestaña en el borde izquierdo abre un tercer panel.
        arrastrar(&mut app, MosaicSource::Tab(reemplazado), (20.0, y));
        assert_eq!(app.document_panes.pane_count(), 3);
        assert!(fuera_de_paneles(&app).is_empty());
    }

    #[test]
    fn soltar_una_cabecera_sobre_la_tira_quita_el_panel_del_mosaico() {
        let (mut app, _) = mosaico_con_tira();
        let capa = app.visible_document_pane_layouts()[0];
        arrastrar(
            &mut app,
            MosaicSource::Pane(capa.pane_id),
            (300.0, TAB_STRIP_Y + 10.0),
        );
        assert_eq!(app.document_panes.pane_count(), 1);
        // La pestaña sigue abierta.
        assert!(app.tab_order.contains(&capa.document_id));
    }

    #[test]
    fn un_arrastre_corto_o_cancelado_no_cambia_el_mosaico() {
        let (mut app, en_la_tira) = mosaico_con_tira();
        let antes = app.visible_document_pane_layouts();
        let y = DOCUMENT_VIEWPORT_TOP + 300.0;
        // Sin pasar el umbral es un clic.
        app.mosaic_drag = Some(MosaicDrag {
            source: MosaicSource::Pane(antes[0].pane_id),
            origin: (0.0, 0.0),
            active: false,
        });
        app.pointer = Some((825.0, y));
        app.finish_mosaic_drag();
        assert_eq!(
            app.visible_document_pane_layouts()[0].document_id,
            antes[0].document_id
        );
        // Una pestaña ya mostrada en un panel no se vuelve a soltar.
        arrastrar(
            &mut app,
            MosaicSource::Tab(antes[0].document_id),
            (825.0, y),
        );
        assert_eq!(app.document_panes.pane_count(), 2);
        assert_eq!(fuera_de_paneles(&app), vec![en_la_tira]);
    }

    #[test]
    fn cerrar_una_pestana_de_un_panel_conserva_la_division_si_hay_otra_en_la_tira() {
        let (mut app, en_la_tira) = mosaico_con_tira();
        let cerrando = app.document.id;
        assert!(app.document_panes.pane_for_document(cerrando).is_some());
        app.finish_close_active_document_tab();
        // Sigue habiendo dos paneles y la pestaña de la tira ocupa el lugar.
        assert_eq!(app.document_panes.pane_count(), 2);
        assert!(app.document_panes.pane_for_document(en_la_tira).is_some());
        assert!(app.document_panes.pane_for_document(cerrando).is_none());
        assert!(!app.tab_order.contains(&cerrando));
        assert!(fuera_de_paneles(&app).is_empty());

        // Sin pestañas en la tira, cerrar colapsa el panel.
        app.finish_close_active_document_tab();
        assert_eq!(app.document_panes.pane_count(), 1);
    }

