    /// Una copia que quedó de otra sesión: un archivo válido en una carpeta de
    /// pruebas, descrito como lo describiría el almacén.
    fn copia_huerfana(titulo: &str, origen: &str, texto: &str) -> (recovery::Orphan, PathBuf) {
        let carpeta = std::env::temp_dir().join(format!(
            "visor-md-huerfana-{}-{}",
            std::process::id(),
            NEXT_DOCUMENT_ID.fetch_add(1, Ordering::Relaxed)
        ));
        fs::create_dir_all(&carpeta).unwrap();
        let meta = recovery::EntryMeta {
            title: titulo.into(),
            origin_path: origen.into(),
            saved_at: unix_now().saturating_sub(300),
            ..recovery::EntryMeta::default()
        };
        let ruta = carpeta.join("abc123.vmdr");
        fs::write(&ruta, recovery::encode_for_tests(&meta, texto)).unwrap();
        let orphan = recovery::Orphan::for_tests(ruta, meta, texto.len() as u64);
        (orphan, carpeta)
    }

    #[test]
    fn una_fila_de_recuperacion_dice_titulo_origen_y_antiguedad() {
        let (con_origen, carpeta) = copia_huerfana("Biología", "C:/notas/bio.md", "# Bio");
        let ahora = unix_now();
        assert_eq!(
            recovery_row_label(&con_origen, ahora),
            "Biología · bio.md · hace 5 min"
        );
        let (nueva, otra) = copia_huerfana("", "", "texto");
        assert_eq!(
            recovery_row_label(&nueva, ahora),
            "Sin título · documento nuevo · hace 5 min"
        );
        let _ = fs::remove_dir_all(carpeta);
        let _ = fs::remove_dir_all(otra);
    }

    #[test]
    fn restaurar_abre_una_pestana_sin_guardar_con_el_titulo_del_texto() {
        let (orphan, carpeta) = copia_huerfana(
            "Plan de viaje",
            "",
            "# Plan de viaje

reservar hotel
",
        );
        let mut app = App::for_tests(NIGHT);
        app.load_for_test("otro", DocumentMode::Reading);
        let pestanas = app.tab_order.len();
        assert_eq!(
            app.restore_recovery(&orphan),
            RestoreOutcome::Detached(Detached::New)
        );
        assert_eq!(app.tab_order.len(), pestanas + 1);
        assert!(app.document.is_untitled());
        assert!(app.document.is_unsaved(), "queda marcada como sin guardar");
        assert_eq!(app.document.display_name(), "Plan de viaje");
        assert!(app.document.source.to_string().contains("reservar hotel"));
        let _ = fs::remove_dir_all(carpeta);
    }

    /// Como `copia_huerfana`, pero con la huella del archivo de origen.
    fn copia_de_archivo(
        titulo: &str,
        origen: &Path,
        base: &str,
        texto: &str,
    ) -> (recovery::Orphan, PathBuf) {
        let carpeta = std::env::temp_dir().join(format!(
            "visor-md-huerfana-{}-{}",
            std::process::id(),
            NEXT_DOCUMENT_ID.fetch_add(1, Ordering::Relaxed)
        ));
        fs::create_dir_all(&carpeta).unwrap();
        let meta = recovery::EntryMeta {
            title: titulo.into(),
            origin_path: origen.to_string_lossy().into_owned(),
            base: base.into(),
            saved_at: unix_now().saturating_sub(300),
        };
        let ruta = carpeta.join("abc123.vmdr");
        fs::write(&ruta, recovery::encode_for_tests(&meta, texto)).unwrap();
        let orphan = recovery::Orphan::for_tests(ruta, meta, texto.len() as u64);
        (orphan, carpeta)
    }

    fn archivo_de_apuntes(texto: &str) -> (PathBuf, PathBuf, String) {
        let carpeta = std::env::temp_dir().join(format!(
            "visor-md-origen-{}-{}",
            std::process::id(),
            NEXT_DOCUMENT_ID.fetch_add(1, Ordering::Relaxed)
        ));
        fs::create_dir_all(&carpeta).unwrap();
        let ruta = carpeta.join("apuntes.md");
        fs::write(&ruta, texto).unwrap();
        let huella = open_explicit_primary(&ruta, 1 << 20)
            .unwrap()
            .identity
            .fingerprint();
        (carpeta, ruta, huella)
    }

    const BLOQUE_ANOTACIONES: &str = "<!-- visor-md:anotaciones v1\nfrase\n{\"id\":\"a1\",\"tipo\":\"leyenda\",\"color\":\"rosa\"}\n-->";

    fn documento_con_anotaciones(cuerpo: &str) -> DocumentState {
        let texto = format!(
            "{cuerpo}{}",
            anotaciones::sufijo(cuerpo, BLOQUE_ANOTACIONES, "\n")
        );
        recovered_document(texto).expect("el texto es válido")
    }

    #[test]
    fn leer_no_dibuja_el_bloque_ni_lo_suma_al_alto() {
        let cuerpo = "# Título\n\nUn párrafo de estudio.\n";
        let con_bloque = format!(
            "{cuerpo}{}",
            anotaciones::sufijo(cuerpo, BLOQUE_ANOTACIONES, "\n")
        );
        let (separado, bloque) = anotaciones::separar(con_bloque.clone());
        assert!(bloque.is_some());
        let sin = DocumentContentKind::Markdown.prepare_view(cuerpo).unwrap();
        let con = DocumentContentKind::Markdown
            .prepare_view(&separado)
            .unwrap();
        assert_eq!(sin.blocks.len(), con.blocks.len());
        assert_eq!(format!("{:?}", sin.blocks), format!("{:?}", con.blocks));
        // Si el bloque llegara al lector, sí sumaría un bloque (la regresión que se evita).
        let sin_separar = DocumentContentKind::Markdown
            .prepare_view(&con_bloque)
            .unwrap();
        assert!(sin_separar.blocks.len() > con.blocks.len());
    }

    #[test]
    fn recuperacion_restaura_cuerpo_y_anotaciones() {
        let original = documento_con_anotaciones("# Título\n\ntexto\n");
        assert_eq!(original.annotations.as_deref(), Some(BLOQUE_ANOTACIONES));
        assert_eq!(original.source.to_string(), "# Título\n\ntexto\n");
        // Lo que se guarda en la copia y en el registro del gancho de pánico.
        let copia = original.full_text();
        assert!(copia.contains("visor-md:anotaciones"));
        assert_eq!(original.full_snapshot().to_string(), copia);
        let restaurado = recovered_document(copia).unwrap();
        assert_eq!(restaurado.source.to_string(), "# Título\n\ntexto\n");
        assert_eq!(restaurado.annotations, original.annotations);
        // Sin anotaciones, la copia es solo el texto.
        let simple = recovered_document("solo texto".to_string()).unwrap();
        assert_eq!(simple.full_text(), "solo texto");
        assert_eq!(simple.full_snapshot().to_string(), "solo texto");
    }

    #[test]
    fn buscar_y_copiar_ignoran_el_bloque() {
        let mut documento = documento_con_anotaciones("# Título\n\ntexto\n");
        // Las métricas y la búsqueda parten del cuerpo.
        let metricas = documento.live_metrics();
        let sin_bloque = DocumentMetrics::from_source(&documento.source.to_string());
        assert_eq!(metricas, sin_bloque);
        assert!(!documento.source.to_string().contains("anotaciones"));
    }

    #[test]
    fn cuerpo_con_codigo_sin_cerrar_rechaza_guardar_anotaciones_en_el_documento() {
        let mut documento = documento_con_anotaciones("# Título\n\ntexto\n");
        assert_eq!(
            documento.annotations_to_write(&documento.source.to_string()),
            (Some(BLOQUE_ANOTACIONES.to_string()), false)
        );
        // La persona abre una cerca de código al final y no la cierra.
        documento.source = TextBuffer::from_text("# Título\n\n```rust\nfn x() {}\n");
        assert_eq!(
            documento.annotations_to_write(&documento.source.to_string()),
            (None, true)
        );
        // Las anotaciones siguen en memoria: no se pierden, solo no se escriben.
        assert!(documento.annotations.is_some());
    }

    /// Píxeles del color de acento en la franja izquierda de la barra de estado,
    /// donde va la línea contraída de anotaciones.
    fn pixeles_de_acento_en_la_barra_de_estado(app: &mut App, alto: u32) -> usize {
        let acento = app.palette.accent;
        let ancho = 320;
        let pixmap = app.draw_for_test(900, alto);
        let top = alto - STATUS_HEIGHT as u32;
        let datos = pixmap.data();
        let mut cuenta = 0;
        for y in top..alto {
            for x in 0..ancho {
                let i = ((y * 900 + x) * 4) as usize;
                if (datos[i], datos[i + 1], datos[i + 2]) == (acento.0, acento.1, acento.2) {
                    cuenta += 1;
                }
            }
        }
        cuenta
    }

