    fn seleccionar(app: &mut App, desde: (usize, usize), hasta: (usize, usize)) {
        app.selection = Some(DocumentSelection {
            anchor: BlockCursor {
                block: desde.0,
                offset: desde.1,
            },
            focus: BlockCursor {
                block: hasta.0,
                offset: hasta.1,
            },
        });
    }

    #[test]
    fn subrayado_cruza_bloques_y_se_dibuja_por_tramos() {
        let mut app = app_de_estudio();
        assert_eq!(app.document.blocks[1].text, "Una frase importante.");
        seleccionar(&mut app, (1, 4), (2, 4));
        app.perform_action(AppAction::HighlightSelection);
        let parsed = estudio::parse(app.document.annotations.as_deref()).unwrap();
        assert_eq!(
            parsed.registros[0].cita.as_deref(),
            Some("frase** importante.\n\nOtra"),
            "la cita es la fuente Markdown, con su sintaxis"
        );
        let fondo = app.palette.study[0].fill;
        let tramos = app.study_highlight_ranges();
        assert_eq!(tramos.get(&1), Some(&vec![(4, 21, fondo)]));
        assert_eq!(tramos.get(&2), Some(&vec![(0, 4, fondo)]));
        assert_eq!(tramos.get(&0), None);
        // Y se pinta: hay píxeles del fondo de estudio en el lienzo.
        app.selection = None;
        let pixmap = app.draw_for_test(900, 600);
        let pintados = pixmap
            .data()
            .as_chunks::<4>()
            .0
            .iter()
            .filter(|p| (p[0], p[1], p[2]) == fondo)
            .count();
        assert!(pintados > 200, "{pintados}");
    }

    #[test]
    fn la_marca_de_libro_se_pone_se_dibuja_y_aparece_en_el_indice() {
        let mut app = App::for_tests(NIGHT);
        app.load_for_test(
            "# Uno

texto uno

# Dos

texto dos
",
            DocumentMode::Reading,
        );
        let texto = app.document.source.to_string();
        seleccionar(&mut app, (3, 0), (3, 0));
        app.perform_action(AppAction::ToggleBookmark);
        assert!(app.document.is_dirty());
        assert_eq!(app.document.source.to_string(), texto);
        let marcas = app.study_bookmarks();
        assert_eq!(marcas.len(), 1);
        // La marca cae en la sección «Dos» (fila 1 del índice).
        let titulos: Vec<usize> = document_outline(&app.document.blocks)
            .iter()
            .map(|(bloque, _)| *bloque)
            .collect();
        let secciones = app.section_marks_for(&titulos);
        assert!(secciones[0].is_empty());
        assert_eq!(secciones[1].colors, vec![0]);
        // Se dibuja en el margen con el trazo del color.
        let trazo = app.palette.study[0].stroke;
        let pixmap = app.draw_for_test(900, 500);
        let pintados = pixmap
            .data()
            .as_chunks::<4>()
            .0
            .iter()
            .filter(|p| (p[0], p[1], p[2]) == trazo)
            .count();
        assert!(pintados > 20, "{pintados}");
        // Poner otra vez en la misma línea la quita.
        app.perform_action(AppAction::ToggleBookmark);
        assert!(app.study_bookmarks().is_empty());
    }

    #[test]
    fn editar_con_anotaciones_las_desplaza_y_las_deja_sin_lugar_sin_borrarlas() {
        let mut app = app_de_estudio();
        seleccionar(&mut app, (2, 0), (2, 4));
        app.perform_action(AppAction::HighlightSelection);
        // Borrar el texto subrayado en Editar: la anotación queda sin lugar.
        app.document.mode = DocumentMode::SourceEditing;
        let desde = app.document.source.to_string().find("Otra").unwrap();
        app.edit_source(|editor, source| {
            editor.set_cursor(source, desde, false)?;
            editor.set_cursor(source, desde + 4, true)?;
            editor.insert(source, "XXXX")
        });
        assert_eq!(app.orphan_annotation_count(), 1);
        assert!(app.document.annotations.is_some(), "no se borra sola");
        // Deshacer la recupera.
        app.undo_edit();
        assert_eq!(app.orphan_annotation_count(), 0);
        // Al guardar se actualizan la posición y el contexto.
        app.edit_source(|editor, source| {
            editor.set_cursor(source, 0, false)?;
            editor.insert(
                source, "ANTES
",
            )
        });
        app.refresh_annotation_anchors();
        let parsed = estudio::parse(app.document.annotations.as_deref()).unwrap();
        assert_eq!(parsed.registros[0].cita.as_deref(), Some("Otra"));
        assert_eq!(
            parsed.registros[0].pos,
            Some({
                let texto = app.document.source.to_string();
                texto[..texto.find("Otra").unwrap()].chars().count() as u64
            })
        );
        // Quitar las sin lugar no toca las ancladas.
        app.perform_action(AppAction::RemoveLostAnnotations);
        assert!(app.document.annotations.is_some());
    }

    fn pdf_de(markdown: &str, rangos: &StudyRanges) -> String {
        let mut font_cx = FontContext::new();
        register_embedded_fonts(&mut font_cx);
        let mut layout_cx = LayoutContext::new();
        let mut scale_cx = ScaleContext::new();
        let blocks = parse_blocks(markdown).expect("válido").blocks;
        let (bytes, _) = export_pdf_bytes(
            &blocks,
            rangos,
            "t",
            &mut font_cx,
            &mut layout_cx,
            &mut scale_cx,
        );
        String::from_utf8_lossy(&bytes).into_owned()
    }

