    #[test]
    fn un_salto_forzado_antes_de_una_lista_no_la_encima() {
        let mut font_cx = FontContext::new();
        register_embedded_fonts(&mut font_cx);
        let mut layout_cx = LayoutContext::new();
        // El «\» al final de una línea es un salto forzado: el párrafo mide dos
        // líneas aunque su texto sea corto. La estimación (sin maquetar) debe
        // contarlas, o la lista que sigue se dibuja encima.
        let fuente = "# Titulo\n\\\nFaltan las herramientas:\\\n1. Poder subrayar\n";
        let blocks = parse_blocks(fuente).expect("válido").blocks;
        let parrafo = blocks
            .iter()
            .position(|b| matches!(b.kind, Kind::Para) && b.text.contains('\n'))
            .expect("hay un párrafo con salto forzado");
        let (estimado, _, _) = measure_all(
            &blocks,
            &mut font_cx,
            &mut layout_cx,
            800.0,
            1.0,
            false,
            &[],
        );
        let (exacto, _, _) =
            measure_all(&blocks, &mut font_cx, &mut layout_cx, 800.0, 1.0, true, &[]);
        assert!(
            (estimado[parrafo].height - exacto[parrafo].height).abs() < 1.0,
            "estimado {} frente a real {}",
            estimado[parrafo].height,
            exacto[parrafo].height
        );
        assert!(estimado[parrafo + 1].y >= estimado[parrafo].y + exacto[parrafo].height - 1.0);
    }

    #[test]
    fn un_archivo_enviado_por_otra_ventana_se_abre_aqui_y_el_latido_se_renueva() {
        let raiz =
            std::env::temp_dir().join(format!("visor-md-app-ventanas-{}", std::process::id()));
        let _ = fs::remove_dir_all(&raiz);
        let archivo = raiz.join("enviado.md");
        fs::create_dir_all(&raiz).unwrap();
        fs::write(
            &archivo,
            "# Enviado
",
        )
        .unwrap();

        let mut app = App::for_tests(NIGHT);
        app.windows = Some(ventanas::Registry::at(&raiz, 111));
        let otra = ventanas::Registry::at(&raiz, 222);
        // El latido de esta ventana aparece en el registro.
        app.service_windows(Instant::now());
        assert_eq!(otra.others(std::time::SystemTime::now()).len(), 1);
        // La otra ventana le pide abrir un archivo.
        otra.send(111, &ventanas::Message::Open(vec![archivo.clone()]))
            .unwrap();
        let pestanas = app.tab_order.len();
        app.read_mailbox();
        assert!(
            app.tab_order.len() > pestanas || !app.open_requests.is_empty(),
            "la ventana empezó a abrir el archivo"
        );
        assert!(
            app.windows.as_ref().unwrap().take().is_empty(),
            "el mensaje se consumió"
        );
        let _ = fs::remove_dir_all(raiz);
    }

