    fn slots_uniformes(blocks: &[Block], alto: f32) -> Vec<Slot> {
        blocks
            .iter()
            .enumerate()
            .map(|(index, block)| Slot {
                y: index as f32 * alto,
                height: alto,
                x: 0.0,
                kind: block.kind,
            })
            .collect()
    }

    #[test]
    fn exportar_el_corpus_produce_un_pdf_estatico_y_paginado() {
        let mut font_cx = FontContext::new();
        register_embedded_fonts(&mut font_cx);
        let mut layout_cx = LayoutContext::new();
        let mut scale_cx = ScaleContext::new();
        let source = include_str!("../tests/fixtures/commonmark-gfm-reader.md");
        let blocks = parse_blocks(source).expect("el corpus es válido").blocks;
        let (bytes, pages) = export_pdf_bytes(
            &blocks,
            &StudyRanges::new(),
            "Corpus (prueba)",
            &mut font_cx,
            &mut layout_cx,
            &mut scale_cx,
        );
        assert!(pages >= 1);
        let text = String::from_utf8_lossy(&bytes);
        assert!(text.starts_with("%PDF-1.4"));
        assert!(
            text.contains("/Subtype /Form"),
            "los glifos son formas vectoriales"
        );
        assert!(text.contains(" Tr /F1 "), "hay capa de texto para buscar");
        for forbidden in [
            "/JavaScript",
            "/OpenAction",
            "/URI",
            "/Launch",
            "/EmbeddedFile",
            "/AcroForm",
        ] {
            assert!(!text.contains(forbidden), "{forbidden}");
        }
        if let Some(path) = std::env::var_os("VISOR_PDF_OUT") {
            std::fs::write(path, &bytes).expect("se escribe la muestra");
        }

        // Un documento largo se reparte en varias páginas.
        let largo = "Párrafo de prueba con texto suficiente para ocupar una línea.\n\n".repeat(200);
        let blocks = parse_blocks(&largo).expect("válido").blocks;
        let (_, pages) = export_pdf_bytes(
            &blocks,
            &StudyRanges::new(),
            "largo",
            &mut font_cx,
            &mut layout_cx,
            &mut scale_cx,
        );
        assert!(pages > 3, "{pages} páginas");
    }

    /// Los fragmentos `( … ) Tj` de la capa de texto invisible, en el orden en
    /// que están en el PDF, sin espacios.
    fn texto_de_la_capa_del_pdf(markdown: &str) -> String {
        let mut font_cx = FontContext::new();
        register_embedded_fonts(&mut font_cx);
        let mut layout_cx = LayoutContext::new();
        let mut scale_cx = ScaleContext::new();
        let blocks = parse_blocks(markdown).expect("válido").blocks;
        let (bytes, _) = export_pdf_bytes(
            &blocks,
            &StudyRanges::new(),
            "capa",
            &mut font_cx,
            &mut layout_cx,
            &mut scale_cx,
        );
        let contenido = String::from_utf8_lossy(&bytes);
        let mut salida = String::new();
        for linea in contenido.lines().filter(|l| l.contains(" Tr /F1 ")) {
            let (Some(abre), Some(cierra)) = (linea.find('('), linea.rfind(") Tj")) else {
                continue;
            };
            salida.push_str(&linea[abre + 1..cierra]);
        }
        salida.split_whitespace().collect()
    }

    #[test]
    fn la_capa_de_texto_del_pdf_sigue_el_orden_de_los_bloques_sin_duplicar() {
        assert_eq!(
            texto_de_la_capa_del_pdf(
                "# Titulo

Primer parrafo.

Segundo parrafo.
"
            ),
            "TituloPrimerparrafo.Segundoparrafo."
        );
        // Una lista y una cita siguen en orden de lectura.
        assert_eq!(
            texto_de_la_capa_del_pdf(
                "- uno
- dos

> cita
"
            ),
            // La vineta (bullet en WinAnsi, octal 225) es parte del texto que se ve.
            "\\225uno\\225doscita"
        );
        // Una tabla se lee fila por fila y no repite el texto de la fila en cada celda.
        assert_eq!(
            texto_de_la_capa_del_pdf(
                "| A | B |
| --- | --- |
| uno | dos |
"
            ),
            "ABunodos"
        );
        // Un enlace no duplica su texto.
        assert_eq!(
            texto_de_la_capa_del_pdf(
                "Ver [la guia](https://example.com) hoy.
"
            ),
            "Verlaguiahoy."
        );
    }

