    #[test]
    fn las_cabeceras_de_panel_aparecen_solo_al_dividir_y_no_tapan_contenido() {
        let area = PaneGeometry {
            x: 0.0,
            y: 0.0,
            width: 1_000.0,
            height: 600.0,
        };
        let mut panes = DocumentPaneTree::single(1);
        let unica = document_pane_layouts_in(&panes, area);
        assert_eq!(unica[0].geometry, area);

        let primero = panes.first_pane_id();
        panes
            .split_pane(primero, 2, DocumentPaneAxis::Vertical)
            .expect("la división existe");
        let layouts = document_pane_layouts_in(&panes, area);
        for layout in &layouts {
            let header = pane_header_rect(layout.geometry);
            assert_eq!(header.y + header.height, layout.geometry.y);
            assert!(header.y >= area.y);
            assert!(!layout.geometry.contains(header.x + 5.0, header.y + 5.0));
        }
        let header = pane_header_rect(layouts[1].geometry);
        let y = header.y + 10.0;
        assert_eq!(
            pane_header_hit(header, header.x + header.width - 5.0, y),
            Some(PaneHeaderHit::Close)
        );
        let mode_x = pane_header_mode_x(header).expect("hay espacio para el modo");
        assert_eq!(
            pane_header_hit(header, mode_x + PANE_HEADER_MODE_SLOT * 1.5, y),
            Some(PaneHeaderHit::Mode(ModeTarget::Editing))
        );
        assert_eq!(
            pane_header_hit(header, header.x + 20.0, y),
            Some(PaneHeaderHit::Title)
        );
        assert_eq!(pane_header_hit(header, header.x + 20.0, y + 40.0), None);
        let angosta = PaneGeometry {
            width: 200.0,
            ..header
        };
        assert_eq!(pane_header_mode_x(angosta), None);
    }

    #[test]
    fn la_geometria_de_paneles_cubre_el_area_sin_solaparse() {
        let mut panes = DocumentPaneTree::single(1);
        let primero = panes.first_pane_id();
        let segundo = panes
            .split_pane(primero, 2, DocumentPaneAxis::Vertical)
            .expect("la primera división existe");
        let tercero = panes
            .split_pane(segundo, 3, DocumentPaneAxis::Horizontal)
            .expect("la segunda división existe");
        let available = PaneGeometry {
            x: 10.0,
            y: 20.0,
            width: 1_000.0,
            height: 600.0,
        };
        let mut layout = Vec::new();
        panes.layout(available, &mut layout);
        assert_eq!(layout.len(), 3);
        assert_eq!(layout[0].pane_id, primero);
        assert_eq!(layout[0].document_id, 1);
        assert_eq!(layout[0].geometry.width, 500.0);
        assert_eq!(layout[1].document_id, 2);
        assert_eq!(layout[1].pane_id, segundo);
        assert_eq!(
            layout[1].geometry,
            PaneGeometry {
                x: 510.0,
                y: 20.0,
                width: 500.0,
                height: 300.0,
            }
        );
        assert_eq!(layout[2].document_id, 3);
        assert_eq!(layout[2].pane_id, tercero);
        assert_eq!(
            layout[2].geometry,
            PaneGeometry {
                x: 510.0,
                y: 320.0,
                width: 500.0,
                height: 300.0,
            }
        );
        assert_eq!(
            document_pane_at(&layout, 509.0, 21.0).map(|pane| pane.document_id),
            Some(1)
        );
        assert_eq!(
            document_pane_at(&layout, 510.0, 21.0).map(|pane| pane.document_id),
            Some(2)
        );
        assert_eq!(
            document_pane_at(&layout, 510.0, 320.0).map(|pane| pane.document_id),
            Some(3)
        );
        assert_eq!(document_pane_at(&layout, 1_010.0, 20.0), None);
    }

    #[test]
    fn los_paneles_degradan_tamanos_y_referencias_patologicas_sin_panico() {
        let mut panes = DocumentPaneTree::single(1);
        let principal = panes.first_pane_id();
        assert_eq!(panes.split_pane(99, 2, DocumentPaneAxis::Vertical), None);
        assert_eq!(panes.pane_for_document(1), Some(principal));
        assert!(
            panes
                .split_pane(principal, 2, DocumentPaneAxis::Horizontal)
                .is_some()
        );
        assert!(panes.without_document(99).is_some());
        assert!(panes.without_document(1).is_some());
        assert!(DocumentPaneTree::single(1).without_document(1).is_none());

        let malformed = DocumentPaneTree::Split {
            axis: DocumentPaneAxis::Vertical,
            fraction: f32::NAN,
            first: Box::new(DocumentPaneTree::Leaf {
                pane_id: 1,
                document_id: 1,
                scroll: 0.0,
            }),
            second: Box::new(DocumentPaneTree::Leaf {
                pane_id: 2,
                document_id: 2,
                scroll: 0.0,
            }),
        };
        let mut layout = Vec::new();
        malformed.layout(
            PaneGeometry {
                x: 0.0,
                y: 0.0,
                width: 0.0,
                height: 1.0,
            },
            &mut layout,
        );
        assert_eq!(layout.len(), 2);
        assert!(layout.iter().all(|pane| {
            pane.geometry.x.is_finite()
                && pane.geometry.y.is_finite()
                && pane.geometry.width.is_finite()
                && pane.geometry.height.is_finite()
                && pane.geometry.width >= 0.0
                && pane.geometry.height >= 0.0
        }));
        assert_eq!(split_pane_extent(0.0, 0.5), 0.0);
        assert_eq!(split_pane_extent(1.0, 0.5), 1.0);
        assert_eq!(split_pane_extent(10.0, -9.0), 2.0);
        assert_eq!(split_pane_extent(10.0, 9.0), 9.0);
    }

    #[test]
    fn la_transicion_de_tema_es_acotada_y_alcanza_su_destino() {
        let started = Instant::now();
        let transition = ThemeTransition {
            from: NIGHT,
            to: DAY,
            started,
        };

        assert_eq!(transition.palette_at(started), NIGHT);
        assert!(!transition.finished(started));
        assert!(transition.finished(started + THEME_TRANSITION_DURATION));
        assert_eq!(
            transition.palette_at(started + THEME_TRANSITION_DURATION),
            DAY
        );
        assert!(
            transition.next_frame_at(started) > started,
            "un cuadro futuro evita redibujar en bucle"
        );
    }

    #[test]
    fn el_indicador_de_modo_anima_sin_rebasar_sus_destinos() {
        let started = Instant::now();
        let transition = ModeTransition {
            from_slot: mode_target_slot(ModeTarget::Reading),
            to_slot: mode_target_slot(ModeTarget::Compare),
            started,
        };

        assert_eq!(transition.position_at(started), 0.0);
        let middle = transition.position_at(started + MODE_SWITCH_TRANSITION_DURATION / 2);
        assert!(middle > 0.0 && middle < 2.0);
        assert_eq!(
            transition.position_at(started + MODE_SWITCH_TRANSITION_DURATION),
            2.0
        );
        assert!(transition.finished(started + MODE_SWITCH_TRANSITION_DURATION));
        assert!(transition.next_frame_at(started) > started);
        assert_eq!(
            mode_target_for_document(DocumentMode::SourceEditing),
            ModeTarget::Editing
        );
    }

