    #[test]
    fn texto_inerte_permanece_literal_despues_de_editar_y_actualizar_vista() {
        let mut document = DocumentState::untitled();
        document.path = "datos.json".to_string();
        document.content_kind = DocumentContentKind::for_path(std::path::Path::new(&document.path));
        document.mode = DocumentMode::Reading;
        document.source = TextBuffer::from_text("**literal**\n# tampoco es título");

        let outcome = document
            .content_kind
            .prepare_view(&document.source.to_string())
            .unwrap();
        assert_eq!(outcome.degradation, Some(Degradation::TextOnly));
        apply_view_outcome(&mut document, outcome);
        assert!(
            document
                .blocks
                .iter()
                .all(|block| matches!(block.kind, Kind::Code))
        );
        assert_eq!(document.blocks[0].text, "**literal**");
        assert_eq!(document.blocks[1].text, "# tampoco es título");

        document
            .source_editor
            .set_cursor(&document.source, document.source.len_bytes(), false)
            .unwrap();
        document
            .source_editor
            .insert(&mut document.source, "\n- sigue siendo texto")
            .unwrap();
        let outcome = document
            .content_kind
            .prepare_view(&document.source.to_string())
            .unwrap();
        apply_view_outcome(&mut document, outcome);

        assert_eq!(document.safe_mode, Some(Degradation::TextOnly));
        assert!(
            document
                .rendered_blocks
                .iter()
                .all(|block| matches!(block.kind, Kind::Code))
        );
        assert_eq!(document.rendered_blocks[2].text, "- sigue siendo texto");
        assert_eq!(
            DocumentContentKind::for_path(std::path::Path::new("nota.md")),
            DocumentContentKind::Markdown
        );
    }

    #[test]
    fn la_vista_de_fuente_actualiza_solo_lineas_afectadas_y_conserva_rangos() {
        let mut source = TextBuffer::from_text("uno\nDOS\ntres\n");
        let previous = safe_buffer_blocks(&source).expect("la fuente inicial es válida");
        let mut editor = SourceEditor::new();
        editor.set_cursor(&source, 7, false).unwrap();
        editor.insert(&mut source, "\ncuatro").unwrap();
        let change = editor.last_change().expect("la edición deja un parche");

        let refreshed = refresh_safe_buffer_blocks_incrementally(&previous, &source, change)
            .expect("la actualización es válida")
            .expect("el vecindario se puede actualizar");
        let complete = safe_buffer_blocks(&source).expect("el respaldo completo es válido");
        let signature = |blocks: &[Block]| {
            blocks
                .iter()
                .map(|block| (block.text.clone(), block.source))
                .collect::<Vec<_>>()
        };
        assert_eq!(signature(&refreshed), signature(&complete));
    }

    #[test]
    fn la_vista_de_fuente_incremental_respeta_unicode_y_borrado_de_lineas() {
        let mut source = TextBuffer::from_text("áé\nsegunda\ntercera\n");
        let previous = safe_buffer_blocks(&source).expect("la fuente inicial es válida");
        let mut editor = SourceEditor::new();
        editor.set_cursor(&source, "áé\n".len(), false).unwrap();
        editor
            .set_cursor(&source, "áé\nsegunda\n".len(), true)
            .unwrap();
        editor.backspace(&mut source).unwrap();
        let change = editor.last_change().expect("el borrado deja un parche");

        let refreshed = refresh_safe_buffer_blocks_incrementally(&previous, &source, change)
            .expect("la actualización es válida")
            .expect("el vecindario se puede actualizar");
        let complete = safe_buffer_blocks(&source).expect("el respaldo completo es válido");
        assert_eq!(
            refreshed
                .iter()
                .map(|block| (&block.text, block.source))
                .collect::<Vec<_>>(),
            complete
                .iter()
                .map(|block| (&block.text, block.source))
                .collect::<Vec<_>>(),
        );
    }

    #[test]
    fn la_vista_de_fuente_incremental_coincide_con_el_respaldo_en_bordes_de_linea() {
        let original = "α\nbeta\ngamma\n";
        let cases = [
            (0, 0, "inicio "),
            ("α\n".len(), "α\n".len(), "antes de beta\n"),
            ("α\nbeta".len(), "α\nbeta".len(), "\nmitad"),
            ("α\n".len(), "α\nbeta\n".len(), ""),
            ("α\nbeta\ngamma".len(), original.len(), "final"),
        ];

        for (start, end, inserted) in cases {
            let mut source = TextBuffer::from_text(original);
            let previous = safe_buffer_blocks(&source).expect("la fuente inicial es válida");
            let mut editor = SourceEditor::new();
            editor.set_cursor(&source, start, false).unwrap();
            editor.set_cursor(&source, end, true).unwrap();
            editor.insert(&mut source, inserted).unwrap();
            let change = editor.last_change().expect("la edición deja un parche");
            let refreshed = refresh_safe_buffer_blocks_incrementally(&previous, &source, change)
                .expect("la actualización no falla")
                .unwrap_or_else(|| safe_buffer_blocks(&source).expect("el respaldo es válido"));
            let complete = safe_buffer_blocks(&source).expect("el respaldo completo es válido");
            assert_eq!(
                refreshed
                    .iter()
                    .map(|block| (&block.text, block.source))
                    .collect::<Vec<_>>(),
                complete
                    .iter()
                    .map(|block| (&block.text, block.source))
                    .collect::<Vec<_>>(),
                "caso {start}..{end}"
            );
        }
    }

    #[test]
    fn el_cursor_de_fuente_cubre_lf_crlf_lineas_vacias_y_final() {
        let source = TextBuffer::from_text("á\r\n\r\ndos\n\nfinal");
        let blocks = safe_buffer_blocks(&source).expect("la fuente es válida");

        for offset in 0..=source.len_bytes() {
            let mut editor = SourceEditor::new();
            if editor.set_cursor(&source, offset, false).is_ok() {
                let cursor = source_block_cursor_at(&blocks, offset)
                    .unwrap_or_else(|| panic!("sin bloque visible para offset legal {offset}"));
                assert!(
                    cursor.offset <= blocks[cursor.block].text.len(),
                    "el cursor {offset} salió del texto visible"
                );
            }
        }

        let crlf_interior = "á\r".len();
        assert!(
            SourceEditor::new()
                .set_cursor(&source, crlf_interior, false)
                .is_err(),
            "el cursor no puede quedar entre CR y LF"
        );
        assert!(source_selection_at(&blocks, 0, source.len_bytes()).is_some());
        assert!(
            source_selection_at(&blocks, 0, source.len_bytes() + 1).is_none(),
            "una selección imposible debe limpiarse, no reutilizar geometría vieja"
        );
    }

