    #[test]
    fn la_busqueda_local_devuelve_solo_bloques_que_contienen_la_consulta() {
        let blocks = parse_blocks("uno\n\ndos con Clave\n\ntres con ñANDÚ")
            .expect("la fixture debe parsearse")
            .blocks;

        assert_eq!(matching_document_ranges(&blocks, "clave")[0].block, 1);
        assert_eq!(matching_document_ranges(&blocks, "Ñandú")[0].block, 2);
        assert!(matching_document_ranges(&blocks, "ausente").is_empty());
        assert!(matching_document_ranges(&blocks, "").is_empty());
        assert_eq!(
            case_insensitive_match_ranges("Antes ÑANDÚ después", "ñandú"),
            vec![6..13]
        );
        assert_eq!(
            case_insensitive_match_ranges("clave segura", "SEGURA"),
            vec![6..12]
        );
        assert_eq!(
            case_insensitive_match_ranges("clave, CLAVE y Clave", "clave"),
            vec![0..5, 7..12, 15..20]
        );
        assert_eq!(
            matching_document_ranges(&aplanar("clave y clave"), "CLAVE"),
            vec![
                SearchMatch {
                    block: 0,
                    range: 0..5
                },
                SearchMatch {
                    block: 0,
                    range: 8..13
                }
            ]
        );
        assert!(case_insensitive_match_ranges("texto", "").is_empty());
        // Sin distinguir tildes: lo escrito sin tilde encuentra lo acentuado y
        // al revés, y el rango apunta al texto original.
        let texto = "Termina con el golpe de Napoleón.";
        let rangos = case_insensitive_match_ranges(texto, "napoleon");
        assert_eq!(rangos.len(), 1);
        assert_eq!(&texto[rangos[0].clone()], "Napoleón");
        assert_eq!(
            case_insensitive_match_ranges("Napoleon", "NAPOLEÓN").len(),
            1
        );
        assert_eq!(case_insensitive_match_ranges("el año", "ano").len(), 1);
        assert!(case_insensitive_match_ranges("el año", "anos").is_empty());
    }

