    #[test]
    fn una_fila_de_tabla_se_maqueta_por_celdas_sin_separadores() {
        let blocks = aplanar("| izquierda | centro |\n| :--- | :---: |\n| texto | **valor** |");
        let row = blocks
            .iter()
            .find(|block| matches!(block.kind, Kind::TableRow { header: false }))
            .expect("fila de datos");
        let mut font_cx = FontContext::new();
        register_embedded_fonts(&mut font_cx);
        let mut layout_cx = LayoutContext::new();
        let cells = build_table_layouts(row, &mut font_cx, &mut layout_cx, 720.0, 1.0, NIGHT);
        assert_eq!(cells.len(), 2);
        assert!(cells.iter().all(|layout| layout.width() > 0.0));
        assert!(
            cells.iter().all(|layout| layout.width() < 360.0),
            "una celda no debe ocupar toda la fila"
        );
    }

    #[test]
    fn la_seleccion_de_tabla_traduce_cada_celda_sin_incluir_separadores() {
        let blocks = aplanar("| Uno | Dos |\n| --- | --- |\n| tres | cuatro |");
        let row_index = blocks
            .iter()
            .position(|block| {
                matches!(block.kind, Kind::TableRow { header: false })
                    && block
                        .table_cells
                        .first()
                        .is_some_and(|cell| cell.text == "tres")
            })
            .expect("fila de tabla");
        let row = &blocks[row_index];
        let first = table_cell_flat_range(row, 0).expect("primera celda");
        let second = table_cell_flat_range(row, 1).expect("segunda celda");
        assert_eq!(&row.text[first.clone()], "tres");
        assert_eq!(&row.text[second.clone()], "cuatro");

        let selection = DocumentSelection {
            anchor: BlockCursor {
                block: row_index,
                offset: 2,
            },
            focus: BlockCursor {
                block: row_index,
                offset: second.start + 2,
            },
        };
        assert_eq!(
            table_cell_selection_range(selection, row_index, row, 0),
            Some(2..first.len())
        );
        assert_eq!(
            table_cell_selection_range(selection, row_index, row, 1),
            Some(0..2)
        );

        let caret = DocumentSelection::collapsed(BlockCursor {
            block: row_index,
            offset: second.start + 1,
        });
        assert_eq!(
            table_cell_selection_range(caret, row_index, row, 1),
            Some(1..1)
        );
        let separator = DocumentSelection::collapsed(BlockCursor {
            block: row_index,
            offset: first.end + 1,
        });
        assert_eq!(
            table_cell_selection_range(separator, row_index, row, 0),
            None
        );
    }

    #[test]
    fn las_flechas_de_tabla_saltan_separadores_y_conservan_unicode() {
        let blocks = aplanar("| á | dos |\n| --- | --- |");
        let row = blocks
            .iter()
            .find(|block| matches!(block.kind, Kind::TableRow { header: true }))
            .expect("fila de tabla");
        let first = table_cell_flat_range(row, 0).expect("primera celda");
        let second = table_cell_flat_range(row, 1).expect("segunda celda");

        assert_eq!(
            table_adjacent_visible_offset(row, first.start, true),
            first.end
        );
        assert_eq!(
            table_adjacent_visible_offset(row, first.end, true),
            second.start
        );
        assert_eq!(
            table_adjacent_visible_offset(row, second.start, false),
            first.end
        );
        assert_eq!(
            table_adjacent_visible_offset(row, first.end, false),
            first.start
        );
        assert_eq!(
            table_adjacent_visible_offset(row, second.end, true),
            second.end
        );
    }

    #[test]
    fn las_flechas_verticales_de_tabla_conservan_columna_y_unicode() {
        let blocks =
            aplanar("| primera | segunda |\n| --- | --- |\n| áéí | destino |\n| x | último |");
        let header = blocks
            .iter()
            .position(|block| matches!(block.kind, Kind::TableRow { header: true }))
            .expect("encabezado de tabla");
        let first_row = header + 1;
        let second_row = first_row + 1;
        let header_range = table_cell_flat_range(&blocks[header], 0).expect("celda de encabezado");
        let source_range = table_cell_flat_range(&blocks[first_row], 0).expect("celda de origen");
        let target_range = table_cell_flat_range(&blocks[second_row], 0).expect("celda de destino");
        let cursor = BlockCursor {
            block: first_row,
            offset: source_range.start + "á".len(),
        };

        assert_eq!(
            table_vertical_visible_cursor(&blocks, cursor, true),
            Some(BlockCursor {
                block: second_row,
                offset: target_range.start + "x".len(),
            })
        );
        assert_eq!(
            table_vertical_visible_cursor(
                &blocks,
                BlockCursor {
                    block: second_row,
                    offset: target_range.start,
                },
                false,
            ),
            Some(BlockCursor {
                block: first_row,
                offset: source_range.start,
            })
        );
        assert_eq!(
            table_vertical_visible_cursor(&blocks, cursor, false),
            Some(BlockCursor {
                block: header,
                offset: header_range.start + "pr".len(),
            })
        );
    }

